import{_ as d,C as t,o as c,c as p,j as r,a as o,G as a,a2 as i}from"./chunks/framework.BgSoyxN5.js";const b=JSON.parse('{"title":"TickerForge Pricing: Portfolio Stress Testing, Alerts, and Research Plans","description":"Compare TickerForge pricing for portfolio diagnostics, stress testing, Smart Alerts, screeners, and stock research workflows using Telegram Stars.","frontmatter":{"title":"TickerForge Pricing: Portfolio Stress Testing, Alerts, and Research Plans","description":"Compare TickerForge pricing for portfolio diagnostics, stress testing, Smart Alerts, screeners, and stock research workflows using Telegram Stars."},"headers":[],"relativePath":"pricing.md","filePath":"pricing.md","lastUpdated":1785677379000}'),h={name:"pricing.md"};function g(f,e,u,m,k,w){const s=t("TickerForgeComplianceDisclaimer"),n=t("TickerForgeTrustBlock"),l=t("PricingStarsCta");return c(),p("div",null,[e[0]||(e[0]=r("h1",{id:"pricing",tabindex:"-1"},[o("Pricing "),r("a",{class:"header-anchor",href:"#pricing","aria-label":'Permalink to "Pricing"'},"​")],-1)),e[1]||(e[1]=r("p",null,"TickerForge pricing is built around research workflows: stock checks, Smart Alerts, portfolio diagnostics, portfolio stress testing, market context, and screeners. If you are comparing a trading platform with portfolio stress testing pricing, note the distinction: TickerForge is not a broker or execution platform. It is educational decision-support software that helps you review risk, concentration, alerts, and research evidence alongside the broker you already use.",-1)),e[2]||(e[2]=r("p",null,[o("Paid access is currently activated through "),r("strong",null,"Telegram Stars"),o(". USD prices are shown only as a reference while website card payments are being prepared.")],-1)),a(s),a(n,{kind:"pricing"}),e[3]||(e[3]=i('<h2 id="try-this-workflow-before-choosing-a-plan" tabindex="-1">Try This Workflow Before Choosing a Plan <a class="header-anchor" href="#try-this-workflow-before-choosing-a-plan" aria-label="Permalink to &quot;Try This Workflow Before Choosing a Plan&quot;">​</a></h2><ul><li>Start with <a href="/import-portfolio">Import Portfolio</a> if you want to test portfolio health, concentration, sector exposure, and stress-test impact on real holdings.</li><li>Use <a href="/stock-widget">Stock Check</a> if you want to review one ticker before adding it to alerts or a portfolio.</li><li>Open the <a href="/market-widget">Market Regime Widget</a> if you want daily market context before deciding whether to add risk.</li></ul><p>Educational decision-support software. Not financial advice.</p><h2 id="portfolio-stress-testing-pricing" tabindex="-1">Portfolio Stress Testing Pricing <a class="header-anchor" href="#portfolio-stress-testing-pricing" aria-label="Permalink to &quot;Portfolio Stress Testing Pricing&quot;">​</a></h2><p>Portfolio analytics are included in TickerForge plans as research and decision-support tools. Depending on the plan, users can review stock checks, portfolio diagnostics, portfolio health, concentration, sector exposure, cash buffer, stress-test style drawdown sensitivity, market context, and alerts from the same workflow.</p><p>Start with Free if you want a browser-based portfolio snapshot and health check. Standard adds recurring portfolio monitoring and alerts. Pro is designed for deeper portfolio analytics, advanced research views, and export-ready workflows where available.</p><p>TickerForge is not a brokerage, does not execute trades, and does not manage portfolios. Pricing covers analytics software for research workflows, not portfolio management or personalized financial advice.</p><h3 id="portfolio-pricing-faq" tabindex="-1">Portfolio Pricing FAQ <a class="header-anchor" href="#portfolio-pricing-faq" aria-label="Permalink to &quot;Portfolio Pricing FAQ&quot;">​</a></h3><p><strong>Does TickerForge include portfolio stress testing?</strong> Yes. Portfolio diagnostics include stress-test style reports that estimate downside and upside sensitivity from holdings, cash, exposure, and beta assumptions.</p><p><strong>Which plan includes portfolio diagnostics?</strong> Free includes browser diagnostics and demos. Standard adds weekly tracking and alerts. Pro includes advanced portfolio analytics and exports where available.</p><p><strong>Is TickerForge a brokerage?</strong> No. TickerForge does not hold assets, connect to brokerage custody, or execute trades.</p><p><strong>Is this financial advice?</strong> No. TickerForge provides educational decision-support software and research diagnostics, not personalized investment advice.</p><p><strong>Can I use TickerForge before changing my portfolio?</strong> Yes. You can import holdings to review portfolio health, concentration, sector exposure, cash buffer, and stress-test impact before making decisions elsewhere.</p><h2 id="early-access" tabindex="-1">Early Access <a class="header-anchor" href="#early-access" aria-label="Permalink to &quot;Early Access&quot;">​</a></h2><p>TickerForge is in early access. The current early-access offer is:</p><ul><li><strong>Early Access:</strong> <strong>700 Telegram Stars / month</strong> while slots are available;</li><li>includes Standard access during early access;</li><li>price lock for 12 months from activation;</li><li>limited availability while the early-access program is open.</li></ul><p>Current regular plan prices are <strong>1,200 Stars / month</strong> for Standard and <strong>2,000 Stars / month</strong> for Pro.</p><h2 id="compare-plans" tabindex="-1">Compare Plans <a class="header-anchor" href="#compare-plans" aria-label="Permalink to &quot;Compare Plans&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Feature</th><th>Free</th><th>Standard</th><th>Pro</th></tr></thead><tbody><tr><td>Current price</td><td>0 Stars</td><td><strong>1,200 Stars / month</strong> (~$19/mo reference). Early Access may be available at <strong>700 Stars / month</strong>.</td><td><strong>2,000 Stars / month</strong> (~$39/mo reference)</td></tr><tr><td>Stock check and company research view</td><td>Basic access</td><td>Expanded evidence layers</td><td>Expanded evidence layers</td></tr><tr><td>Smart Alerts / watchlist monitoring</td><td>Up to 5 tracked stocks</td><td>Expanded monitoring limits</td><td>Expanded monitoring plus advanced research alerts</td></tr><tr><td>Portfolio diagnostics</td><td>Browser diagnostics and demos</td><td>Weekly tracking and alerts</td><td>Advanced portfolio analytics and exports</td></tr><tr><td>Market regime and stress context</td><td>Public market views</td><td>Market monitoring and saved alerts</td><td>Advanced market and sector workflow access</td></tr><tr><td>Smart Money / insider radar</td><td>Public preview</td><td>Deeper company-level evidence</td><td>Full screener workflow and exports</td></tr><tr><td>Email and Telegram research notifications</td><td>Limited</td><td>Included</td><td>Included with advanced workflows</td></tr><tr><td>Support</td><td>Community / best effort</td><td>Standard support</td><td>Priority support</td></tr></tbody></table>',19)),a(l,{"api-base":"https://api.ticker-forge.com"}),e[4]||(e[4]=i('<h2 id="free" tabindex="-1">Free <a class="header-anchor" href="#free" aria-label="Permalink to &quot;Free&quot;">​</a></h2><p>Use Free to understand the product and run basic research workflows:</p><ul><li>browser stock checks;</li><li>public Smart Money and insider radar preview;</li><li>manual portfolio diagnostic preview;</li><li>public market regime widget;</li><li>up to 5 tracked stocks for basic Smart Alerts;</li><li>limited portfolio tracking trial after creating/importing a portfolio in Telegram.</li></ul><p>Free does not include expanded monitoring limits, full screener exports, advanced portfolio reports, or priority support.</p><h2 id="standard" tabindex="-1">Standard <a class="header-anchor" href="#standard" aria-label="Permalink to &quot;Standard&quot;">​</a></h2><p>Standard is for users who want recurring software monitoring and deeper research workflows:</p><ul><li>expanded Smart Alerts and watchlist monitoring;</li><li>recurring portfolio health monitoring;</li><li>saved research context in email or Telegram;</li><li>expanded stock evidence layers;</li><li>deeper Smart Money and insider activity context;</li><li>market regime and portfolio-risk monitoring workflows.</li></ul><p>Standard is currently <strong>1,200 Telegram Stars / month</strong>. Early Access may be available at <strong>700 Telegram Stars / month</strong> while slots remain.</p><h2 id="pro" tabindex="-1">Pro <a class="header-anchor" href="#pro" aria-label="Permalink to &quot;Pro&quot;">​</a></h2><p>Pro is for users who need advanced screener and portfolio analytics workflows:</p><ul><li>full Smart Money and insider screener workflow;</li><li>advanced filters and export-ready research views;</li><li>advanced portfolio diagnostics such as concentration, volatility, stress, and correlation-style views where available;</li><li>priority support;</li><li>advanced research notifications and monitoring workflows.</li></ul><p>Pro is currently <strong>2,000 Telegram Stars / month</strong> through the bot.</p><h2 id="delivery-email-and-telegram" tabindex="-1">Delivery: Email And Telegram <a class="header-anchor" href="#delivery-email-and-telegram" aria-label="Permalink to &quot;Delivery: Email And Telegram&quot;">​</a></h2><p>TickerForge can send follow-up research by email, Telegram, or both.</p><ul><li><strong>Email</strong> is useful for stock snapshots, portfolio snapshot PDFs, alert summaries, and payment waitlist updates.</li><li><strong>Telegram</strong> is required for Stars payment, account activation, bot menus, portfolio creation/import, and Telegram alerts.</li></ul><p>If you start from a website widget, the Free path asks for email or Telegram after the stock or portfolio result. If you choose Standard or Pro access, the widget sends you to this pricing page so you can choose the current payment option without repeating the same delivery step twice.</p><h2 id="widget-flow-logic" tabindex="-1">Widget Flow Logic <a class="header-anchor" href="#widget-flow-logic" aria-label="Permalink to &quot;Widget Flow Logic&quot;">​</a></h2><p><strong>Stock Check:</strong> Free continues to email or Telegram and can enable one Smart Alert, up to the free allowance of 5 tracked stocks. When the allowance is exhausted, upgrade prompts should point back to this pricing page or the bot upgrade flow.</p><p><strong>Portfolio Diagnostics:</strong> Free sends the portfolio snapshot and trial context by email. To create/import the portfolio and enable tracking, continue in Telegram. The free trial should count tracking runs for the portfolio instead of resetting just because a new portfolio snapshot was created.</p><p><strong>Standard / Pro Interest:</strong> Choosing paid access from a widget records the product context and opens pricing. It should not ask the same email/Telegram question again inside the widget.</p><h2 id="what-tickerforge-does-not-include" tabindex="-1">What TickerForge Does Not Include <a class="header-anchor" href="#what-tickerforge-does-not-include" aria-label="Permalink to &quot;What TickerForge Does Not Include&quot;">​</a></h2><p>TickerForge does not include:</p><ul><li>brokerage services;</li><li>trade execution;</li><li>custody of assets;</li><li>personalized advisory services;</li><li>managed portfolios;</li><li>promises of investment outcomes.</li></ul><h2 id="cancellation-and-refunds" tabindex="-1">Cancellation And Refunds <a class="header-anchor" href="#cancellation-and-refunds" aria-label="Permalink to &quot;Cancellation And Refunds&quot;">​</a></h2><p>Subscriptions can be cancelled according to the payment provider and plan rules. Manage-subscription and refund links may be available through the receipt, customer portal, or support flow for the provider used at checkout.</p><p>Read the <a href="/refund-policy">Refund and Cancellation Policy</a> for details.</p><h2 id="related-read-next" tabindex="-1">Related / Read Next <a class="header-anchor" href="#related-read-next" aria-label="Permalink to &quot;Related / Read Next&quot;">​</a></h2><ul><li><a href="/demo">See how TickerForge works</a></li><li><a href="/features">Explore TickerForge features</a></li><li><a href="/stock-widget">Check a stock</a></li><li><a href="/portfolio-diagnostics">Try portfolio diagnostics demo</a></li><li><a href="/import-portfolio">Analyze your own portfolio</a></li><li><a href="/terms">Read the Terms</a></li></ul>',28))])}const T=d(h,[["render",g]]);export{b as __pageData,T as default};
